```import { Denops } from "<https://deno.land/x/denops_std@v1.8.1/mod.ts>";
import { ensureArray } from "<https://deno.land/x/unknownutil@v1.1.0/mod.ts>";

export async function main(denops: Denops): Promise&lt;void&gt; {
  denops.dispacher = {
    async bytelist2char(...bytes: unknown[]): Promise&lt;unknown&gt; {
      ensureArray(bytes);
      return (new TextDecoder("utf-8")).decode(Uint8Array.from(bytes as number[]).buffer);
    },
  }
}```
